              <pre><span class="c1"># загружаем данные из БД</span>
<span class="kn">import</span> <span class="nn">pandas</span> <span class="k">as</span> <span class="nn">pd</span>
<span class="kn">from</span> <span class="nn">sqlalchemy</span> <span class="kn">import</span> <span class="n">create_engine</span>

<span class="n">db_string</span> <span class="o">=</span> <span class="sa">f</span><span class="s2">"postgresql://hakaton_admin:fyT6r5Kd94Nko4d@94.142.142.59:5432/hakaton2_db"</span>
<span class="n">engine</span> <span class="o">=</span> <span class="n">create_engine</span><span class="p">(</span><span class="n">db_string</span><span class="p">)</span>

<span class="c1"># Загрузка данныx</span>
<span class="n">query_customer_items</span> <span class="o">=</span> <span class="s2">"select c.customer_unique_id, date(o.order_purchase_timestamp) as order_date, sum(oic.price) from customers c left join orders o on o.customer_id = c.customer_id left join orders_items_clear oic on oic.order_id = o.order_id group by c.customer_unique_id, date(o.order_purchase_timestamp), o.order_status having sum(oic.price) is not null;"</span>
<span class="n">customer_items</span> <span class="o">=</span> <span class="n">pd</span><span class="o">.</span><span class="n">read_sql_query</span><span class="p">(</span><span class="n">query_customer_items</span><span class="p">,</span> <span class="n">engine</span><span class="p">)</span>
