          <div class="cm-editor cm-s-jupyter">
            <div class="highlight hl-ipython3">
              <pre><span class="k">def</span> <span class="nf">calculate_rfm_metrics</span><span class="p">(</span><span class="n">customer_items</span><span class="p">,</span> <span class="n">end_date</span><span class="o">=</span><span class="s1">'2024-01-01'</span><span class="p">,</span> <span class="n">customer_id_column</span><span class="o">=</span><span class="s1">'customer_unique_id'</span><span class="p">,</span>
                          <span class="n">date_column</span><span class="o">=</span><span class="s1">'order_date'</span><span class="p">,</span> <span class="n">monetary_column</span><span class="o">=</span><span class="s1">'sum'</span><span class="p">):</span>
<span class="w">    </span><span class="sd">"""</span>
<span class="sd">    Вычисляет RFM-метрики на основе данных о клиентах и их заказах.</span>

<span class="sd">    Args:</span>
<span class="sd">        customer_items (pd.DataFrame): DataFrame с данными о клиентах, датах заказов и суммах заказов.</span>
<span class="sd">        end_date (str): Дата окончания анализа в формате 'YYYY-MM-DD' (по умолчанию '2024-01-01').</span>
<span class="sd">        customer_id_column (str): Название столбца с идентификатором клиента (по умолчанию 'customer_unique_id').</span>
<span class="sd">        date_column (str): Название столбца с датой заказа (по умолчанию 'order_date').</span>
<span class="sd">        monetary_column (str): Название столбца с суммой заказа (по умолчанию 'sum').</span>

<span class="sd">    Returns:</span>
<span class="sd">        pd.DataFrame: DataFrame с RFM-метриками, содержащий столбцы 'recency (days)', 'frequency', 'monetary_value'.</span>
<span class="sd">    """</span>

    <span class="n">RFM</span> <span class="o">=</span> <span class="n">pd</span><span class="o">.</span><span class="n">DataFrame</span><span class="p">(</span><span class="n">customer_items</span><span class="p">)</span>
    <span class="n">RFM</span><span class="p">[</span><span class="n">date_column</span><span class="p">]</span> <span class="o">=</span> <span class="n">pd</span><span class="o">.</span><span class="n">to_datetime</span><span class="p">(</span><span class="n">RFM</span><span class="p">[</span><span class="n">date_column</span><span class="p">])</span>

    <span class="n">NOW</span> <span class="o">=</span> <span class="n">pd</span><span class="o">.</span><span class="n">to_datetime</span><span class="p">(</span><span class="n">end_date</span><span class="p">)</span>

    <span class="n">rfmTable</span> <span class="o">=</span> <span class="n">RFM</span><span class="o">.</span><span class="n">groupby</span><span class="p">(</span><span class="n">customer_id_column</span><span class="p">)</span><span class="o">.</span><span class="n">agg</span><span class="p">({</span>
        <span class="n">date_column</span><span class="p">:</span> <span class="k">lambda</span> <span class="n">x</span><span class="p">:</span> <span class="p">(</span><span class="n">NOW</span> <span class="o">-</span> <span class="n">x</span><span class="o">.</span><span class="n">max</span><span class="p">())</span><span class="o">.</span><span class="n">days</span><span class="p">,</span>  <span class="c1"># Recency</span>
        <span class="n">customer_id_column</span><span class="p">:</span> <span class="s1">'count'</span><span class="p">,</span>  <span class="c1"># Frequency</span>
        <span class="n">monetary_column</span><span class="p">:</span> <span class="k">lambda</span> <span class="n">x</span><span class="p">:</span> <span class="n">x</span><span class="o">.</span><span class="n">sum</span><span class="p">()</span>  <span class="c1"># Monetary Value</span>
    <span class="p">})</span>

    <span class="n">rfmTable</span><span class="o">.</span><span class="n">rename</span><span class="p">(</span>
        <span class="n">columns</span><span class="o">=</span><span class="p">{</span><span class="n">date_column</span><span class="p">:</span> <span class="s1">'recency (days)'</span><span class="p">,</span> <span class="n">customer_id_column</span><span class="p">:</span> <span class="s1">'frequency'</span><span class="p">,</span> <span class="n">monetary_column</span><span class="p">:</span> <span class="s1">'monetary_value'</span><span class="p">},</span>
        <span class="n">inplace</span><span class="o">=</span><span class="kc">True</span><span class="p">)</span>

    <span class="n">rfmTable</span><span class="p">[</span><span class="s1">'recency (days)'</span><span class="p">]</span> <span class="o">=</span> <span class="n">rfmTable</span><span class="p">[</span><span class="s1">'recency (days)'</span><span class="p">]</span><span class="o">.</span><span class="n">astype</span><span class="p">(</span>
        <span class="nb">int</span><span class="p">)</span>  <span class="c1"># Преобразуем в целые числа (recency (days))</span>

    <span class="k">return</span> <span class="n">rfmTable</span>

<span class="n">RFM_price</span><span class="o">=</span> <span class="n">calculate_rfm_metrics</span><span class="p">(</span><span class="n">customer_items</span><span class="p">,</span> <span class="n">end_date</span><span class="o">=</span><span class="s1">'2024-01-01'</span><span class="p">,</span> <span class="n">customer_id_column</span><span class="o">=</span><span class="s1">'customer_unique_id'</span><span class="p">,</span>
                          <span class="n">date_column</span><span class="o">=</span><span class="s1">'order_date'</span><span class="p">,</span> <span class="n">monetary_column</span><span class="o">=</span><span class="s1">'sum'</span><span class="p">)</span>
<span class="n">display</span><span class="p">(</span><span class="n">RFM_price</span><span class="p">)</span>
</pre>
