  <div class="jp-Cell jp-CodeCell jp-Notebook-cell">
    <div class="jp-Cell-inputWrapper" tabindex="0">
      <div class="jp-Collapser jp-InputCollapser jp-Cell-inputCollapser"></div>
      <div>
        <div class="jp-CodeMirrorEditor jp-Editor jp-InputArea-editor" data-type="inline">
          <div class="cm-editor cm-s-jupyter">
            <div class="highlight hl-ipython3">
              <pre><span class="c1"># 4. Расчет RFM-скора</span>
<span class="k">def</span> <span class="nf">calculate_rfm_score_and_segment</span><span class="p">(</span><span class="n">rfm_table</span><span class="p">):</span>
<span class="w">    </span><span class="sd">"""</span>
<span class="sd">    Вычисляет RFM-скор и сегментирует клиентов на основе RFM-метрик, выводя описания сегментов и количество клиентов в каждом сегменте.</span>

<span class="sd">    Args:</span>
<span class="sd">        rfm_table (pd.DataFrame): DataFrame с RFM-метриками и рангами ('R', 'F', 'M').</span>

<span class="sd">    Returns:</span>
<span class="sd">        pd.DataFrame: DataFrame с добавленными столбцами 'RFM_Score' и 'Segment'.</span>
<span class="sd">    """</span>

    <span class="n">rfm_table</span><span class="p">[</span><span class="s1">'R'</span><span class="p">]</span> <span class="o">=</span> <span class="n">rfm_table</span><span class="p">[</span><span class="s1">'R'</span><span class="p">]</span><span class="o">.</span><span class="n">astype</span><span class="p">(</span><span class="nb">str</span><span class="p">)</span>
    <span class="n">rfm_table</span><span class="p">[</span><span class="s1">'F'</span><span class="p">]</span> <span class="o">=</span> <span class="n">rfm_table</span><span class="p">[</span><span class="s1">'F'</span><span class="p">]</span><span class="o">.</span><span class="n">astype</span><span class="p">(</span><span class="nb">str</span><span class="p">)</span>
    <span class="n">rfm_table</span><span class="p">[</span><span class="s1">'M'</span><span class="p">]</span> <span class="o">=</span> <span class="n">rfm_table</span><span class="p">[</span><span class="s1">'M'</span><span class="p">]</span><span class="o">.</span><span class="n">astype</span><span class="p">(</span><span class="nb">str</span><span class="p">)</span>

    <span class="n">rfm_table</span><span class="p">[</span><span class="s1">'RFM_Score'</span><span class="p">]</span> <span class="o">=</span> <span class="n">rfm_table</span><span class="p">[</span><span class="s1">'R'</span><span class="p">]</span> <span class="o">+</span> <span class="n">rfm_table</span><span class="p">[</span><span class="s1">'F'</span><span class="p">]</span> <span class="o">+</span> <span class="n">rfm_table</span><span class="p">[</span><span class="s1">'M'</span><span class="p">]</span>

    <span class="c1"># 5. Сегментация клиентов и описание сегментов</span>
    <span class="k">def</span> <span class="nf">segment_customers</span><span class="p">(</span><span class="n">row</span><span class="p">):</span>
        <span class="n">r</span><span class="p">,</span> <span class="n">f</span><span class="p">,</span> <span class="n">m</span> <span class="o">=</span> <span class="n">row</span><span class="p">[</span><span class="s1">'R'</span><span class="p">],</span> <span class="n">row</span><span class="p">[</span><span class="s1">'F'</span><span class="p">],</span> <span class="n">row</span><span class="p">[</span><span class="s1">'M'</span><span class="p">]</span>  <span class="c1"># Для удобства</span>
        <span class="n">rfm_score</span> <span class="o">=</span> <span class="n">row</span><span class="p">[</span><span class="s1">'RFM_Score'</span><span class="p">]</span>

        <span class="k">if</span> <span class="n">rfm_score</span> <span class="o">==</span> <span class="s1">'444'</span><span class="p">:</span>
            <span class="k">return</span> <span class="s1">'Best Customers'</span>  <span class="c1"># R=4, F=4, M=4</span>
        <span class="k">elif</span> <span class="n">r</span> <span class="ow">in</span> <span class="p">[</span><span class="s1">'4'</span><span class="p">,</span> <span class="s1">'3'</span><span class="p">]</span> <span class="ow">and</span> <span class="n">f</span> <span class="ow">in</span> <span class="p">[</span><span class="s1">'3'</span><span class="p">,</span> <span class="s1">'4'</span><span class="p">]:</span>
            <span class="k">return</span> <span class="s1">'Loyal Customers'</span>  <span class="c1"># Высокий R и F</span>
        <span class="k">elif</span> <span class="n">r</span> <span class="ow">in</span> <span class="p">[</span><span class="s1">'4'</span><span class="p">,</span> <span class="s1">'3'</span><span class="p">]</span> <span class="ow">and</span> <span class="n">m</span> <span class="ow">in</span> <span class="p">[</span><span class="s1">'3'</span><span class="p">,</span> <span class="s1">'4'</span><span class="p">]:</span>
            <span class="k">return</span> <span class="s1">'Big Spenders'</span>  <span class="c1"># Высокий R и M</span>
        <span class="k">elif</span> <span class="n">r</span> <span class="o">==</span> <span class="s1">'4'</span> <span class="ow">and</span> <span class="n">f</span> <span class="o">==</span> <span class="s1">'1'</span> <span class="ow">and</span> <span class="n">m</span> <span class="ow">in</span> <span class="p">[</span><span class="s1">'3'</span><span class="p">,</span> <span class="s1">'4'</span><span class="p">]:</span>
            <span class="k">return</span> <span class="s1">'New Big Spenders'</span>  <span class="c1"># Новые, но уже много тратят</span>
        <span class="k">elif</span> <span class="n">r</span> <span class="o">==</span> <span class="s1">'4'</span> <span class="ow">and</span> <span class="n">f</span> <span class="o">==</span> <span class="s1">'1'</span> <span class="ow">and</span> <span class="n">m</span> <span class="ow">in</span> <span class="p">[</span><span class="s1">'1'</span><span class="p">,</span> <span class="s1">'2'</span><span class="p">]:</span>
            <span class="k">return</span> <span class="s1">'New Low Spenders'</span>  <span class="c1"># Недавние покупатели, мало тратят</span>
        <span class="k">elif</span> <span class="n">r</span> <span class="o">==</span> <span class="s1">'4'</span> <span class="ow">and</span> <span class="n">f</span> <span class="o">==</span> <span class="s1">'1'</span><span class="p">:</span>
            <span class="k">return</span> <span class="s1">'New Customers'</span>  <span class="c1"># Новый, но еще не лояльный</span>
        <span class="k">elif</span> <span class="n">r</span> <span class="o">==</span> <span class="s1">'1'</span> <span class="ow">and</span> <span class="n">f</span> <span class="o">==</span> <span class="s1">'1'</span><span class="p">:</span>
            <span class="k">return</span> <span class="s1">'Lost Customers'</span>  <span class="c1"># Потерянные</span>
        <span class="k">elif</span> <span class="n">r</span> <span class="ow">in</span> <span class="p">[</span><span class="s1">'1'</span><span class="p">,</span> <span class="s1">'2'</span><span class="p">]</span> <span class="ow">and</span> <span class="n">f</span> <span class="ow">in</span> <span class="p">[</span><span class="s1">'3'</span><span class="p">,</span> <span class="s1">'4'</span><span class="p">]:</span>
            <span class="k">return</span> <span class="s1">'Churning Loyalists'</span>  <span class="c1"># Лояльные, но уходящие</span>
        <span class="k">elif</span> <span class="n">r</span> <span class="ow">in</span> <span class="p">[</span><span class="s1">'1'</span><span class="p">,</span> <span class="s1">'2'</span><span class="p">]</span> <span class="ow">and</span> <span class="n">m</span> <span class="ow">in</span> <span class="p">[</span><span class="s1">'3'</span><span class="p">,</span> <span class="s1">'4'</span><span class="p">]:</span>
            <span class="k">return</span> <span class="s1">'Churning Spenders'</span>  <span class="c1"># Тратят много, но уходят</span>
        <span class="k">elif</span> <span class="n">r</span> <span class="o">==</span> <span class="s1">'4'</span> <span class="ow">and</span> <span class="n">m</span> <span class="o">==</span> <span class="s1">'1'</span><span class="p">:</span>
            <span class="k">return</span> <span class="s1">'Discount Shoppers'</span>  <span class="c1"># Покупают недавно, но тратят мало</span>
        <span class="k">elif</span> <span class="n">r</span> <span class="ow">in</span> <span class="p">[</span><span class="s1">'3'</span><span class="p">,</span> <span class="s1">'4'</span><span class="p">]</span> <span class="ow">and</span> <span class="n">f</span> <span class="ow">in</span> <span class="p">[</span><span class="s1">'1'</span><span class="p">,</span> <span class="s1">'2'</span><span class="p">]:</span>
            <span class="k">return</span> <span class="s1">'Promising'</span>  <span class="c1"># Совершают покупки недавно, но редко</span>
        <span class="k">elif</span> <span class="n">r</span> <span class="o">==</span> <span class="s1">'1'</span> <span class="ow">and</span> <span class="n">m</span> <span class="o">==</span> <span class="s1">'4'</span><span class="p">:</span>
            <span class="k">return</span> <span class="s1">'Resurrect Spenders'</span>  <span class="c1"># Тратят много, но редко</span>
        <span class="k">elif</span> <span class="n">f</span> <span class="o">==</span> <span class="s1">'4'</span> <span class="ow">and</span> <span class="n">m</span> <span class="o">==</span> <span class="s1">'1'</span><span class="p">:</span>
            <span class="k">return</span> <span class="s1">'Frequent Low Spenders'</span>  <span class="c1"># Часто покупают, но тратят мало</span>
        <span class="k">elif</span> <span class="n">rfm_score</span> <span class="ow">in</span> <span class="p">[</span><span class="s1">'222'</span><span class="p">,</span> <span class="s1">'223'</span><span class="p">,</span> <span class="s1">'232'</span><span class="p">,</span> <span class="s1">'322'</span><span class="p">]:</span>
            <span class="k">return</span> <span class="s1">'Mid-Range'</span>  <span class="c1"># Средние значения по всем параметрам</span>
        <span class="k">else</span><span class="p">:</span>
            <span class="k">return</span> <span class="s1">'Other Customers'</span>

    <span class="n">rfm_table</span><span class="p">[</span><span class="s1">'Segment'</span><span class="p">]</span> <span class="o">=</span> <span class="n">rfm_table</span><span class="o">.</span><span class="n">apply</span><span class="p">(</span><span class="n">segment_customers</span><span class="p">,</span> <span class="n">axis</span><span class="o">=</span><span class="mi">1</span><span class="p">)</span>

    <span class="c1"># Описание сегментов</span>
    <span class="n">segment_descriptions</span> <span class="o">=</span> <span class="p">{</span>
        <span class="s1">'Best Customers'</span><span class="p">:</span> <span class="s1">'Самые ценные клиенты, которых нужно удерживать и вознаграждать '</span><span class="p">,</span>
        <span class="s1">'Loyal Customers'</span><span class="p">:</span> <span class="s1">'Лояльные клиенты, которые покупают регулярно '</span><span class="p">,</span>
        <span class="s1">'Big Spenders'</span><span class="p">:</span> <span class="s1">'Клиенты, которые тратят много денег '</span><span class="p">,</span>
        <span class="s1">'New Big Spenders'</span><span class="p">:</span> <span class="s1">'Новые клиенты, сразу начинающие тратить большие суммы '</span><span class="p">,</span>
        <span class="s1">'New Low Spenders'</span><span class="p">:</span> <span class="s1">'Недавние покупатели, делающие небольшие покупки '</span><span class="p">,</span>
        <span class="s1">'New Customers'</span><span class="p">:</span> <span class="s1">'Недавние покупатели, которых нужно вовлекать '</span><span class="p">,</span>
        <span class="s1">'Lost Customers'</span><span class="p">:</span> <span class="s1">'Клиенты, которых, вероятно, потеряли '</span><span class="p">,</span>
        <span class="s1">'Churning Loyalists'</span><span class="p">:</span> <span class="s1">'Лояльные клиенты, которые перестали совершать новые покупки '</span><span class="p">,</span>
        <span class="s1">'Churning Spenders'</span><span class="p">:</span> <span class="s1">'Клиенты, которые тратили много денег, но перестали совершать новые покупки '</span><span class="p">,</span>
        <span class="s1">'Discount Shoppers'</span><span class="p">:</span> <span class="s1">'Покупают недавно, но тратят мало '</span><span class="p">,</span>
        <span class="s1">'Promising'</span><span class="p">:</span> <span class="s1">'Совершают покупки недавно, но редко '</span><span class="p">,</span>
        <span class="s1">'Resurrect Spenders'</span><span class="p">:</span> <span class="s1">'Давно не покупали, но тратили много '</span><span class="p">,</span>
        <span class="s1">'Frequent Low Spenders'</span><span class="p">:</span> <span class="s1">'Часто покупают, но тратят мало денег за одну покупку '</span><span class="p">,</span>
        <span class="s1">'Mid-Range'</span><span class="p">:</span> <span class="s1">'Клиенты со средними показателями по всем трем параметрам'</span><span class="p">,</span>
        <span class="s1">'Other Customers'</span><span class="p">:</span> <span class="s1">'Клиенты, не вошедшие ни в один из сегментов выше'</span>
    <span class="p">}</span>

    <span class="c1"># Вывод описаний и количества клиентов в каждом сегменте</span>
    <span class="nb">print</span><span class="p">(</span><span class="s2">"</span><span class="se">\n</span><span class="s2">Сегментация клиентов:"</span><span class="p">)</span>
    <span class="n">segment_counts</span> <span class="o">=</span> <span class="n">rfm_table</span><span class="p">[</span><span class="s1">'Segment'</span><span class="p">]</span><span class="o">.</span><span class="n">value_counts</span><span class="p">()</span>
    <span class="k">for</span> <span class="n">segment</span><span class="p">,</span> <span class="n">count</span> <span class="ow">in</span> <span class="n">segment_counts</span><span class="o">.</span><span class="n">items</span><span class="p">():</span>
        <span class="n">description</span> <span class="o">=</span> <span class="n">segment_descriptions</span><span class="o">.</span><span class="n">get</span><span class="p">(</span><span class="n">segment</span><span class="p">,</span> <span class="s2">"Описание отсутствует"</span><span class="p">)</span>
        <span class="n">display</span><span class="p">(</span><span class="sa">f</span><span class="s2">"</span><span class="si">{</span><span class="n">segment</span><span class="si">}</span><span class="s2">: </span><span class="si">{</span><span class="n">description</span><span class="si">}</span><span class="s2"> - Количество клиентов: </span><span class="si">{</span><span class="n">count</span><span class="si">}</span><span class="s2">"</span><span class="p">)</span>

    <span class="k">return</span> <span class="n">rfm_table</span>

<span class="n">rfmTable</span> <span class="o">=</span> <span class="n">pd</span><span class="o">.</span><span class="n">DataFrame</span><span class="p">(</span><span class="n">rfmTable</span><span class="p">)</span>

<span class="n">RFM_price</span> <span class="o">=</span> <span class="n">calculate_rfm_score_and_segment</span><span class="p">(</span><span class="n">rfmTable</span><span class="p">)</span>
<span class="n">display</span><span class="p">(</span><span class="s2">"</span><span class="se">\n</span><span class="s2">RFM Table with RFM Score and Segments:</span><span class="se">\n</span><span class="s2">"</span><span class="p">,</span> <span class="n">RFM_price</span><span class="o">.</span><span class="n">head</span><span class="p">())</span>
</pre>
