  <div class="jp-Cell jp-CodeCell jp-Notebook-cell">
    <div class="jp-Cell-inputWrapper" tabindex="0">
      <div class="jp-Collapser jp-InputCollapser jp-Cell-inputCollapser"></div>
      <div>
        <div class="jp-CodeMirrorEditor jp-Editor jp-InputArea-editor" data-type="inline">
          <div class="cm-editor cm-s-jupyter">
            <div class="highlight hl-ipython3">
              <pre><span class="c1">#Segment Distribution Chart (с использованием Matplotlib):</span>


<span class="kn">import</span> <span class="nn">pandas</span> <span class="k">as</span> <span class="nn">pd</span>
<span class="kn">import</span> <span class="nn">matplotlib.pyplot</span> <span class="k">as</span> <span class="nn">plt</span>
<span class="kn">import</span> <span class="nn">matplotlib.colors</span> <span class="k">as</span> <span class="nn">mcolors</span>

<span class="k">def</span> <span class="nf">create_segment_distribution_pie</span><span class="p">(</span><span class="n">rfm_table</span><span class="p">,</span> <span class="n">title</span><span class="o">=</span><span class="s2">"Customer Segment Distribution"</span><span class="p">):</span>
<span class="w">    </span><span class="sd">"""</span>
<span class="sd">    Сегментирует клиентов на основе RFM-метрик и отображает распределение сегментов в виде круговой диаграммы с легендой.</span>

<span class="sd">    Args:</span>
<span class="sd">        rfm_table (pd.DataFrame): DataFrame с RFM-метриками и рангами ('R', 'F', 'M', 'RFM_Score').</span>
<span class="sd">        title (str): Заголовок графика.</span>

<span class="sd">    Returns:</span>
<span class="sd">        None (отображает график)</span>
<span class="sd">    """</span>

    <span class="k">def</span> <span class="nf">segment_customers</span><span class="p">(</span><span class="n">row</span><span class="p">):</span>
        <span class="k">try</span><span class="p">:</span>
            <span class="n">r</span><span class="p">,</span> <span class="n">f</span><span class="p">,</span> <span class="n">m</span> <span class="o">=</span> <span class="nb">str</span><span class="p">(</span><span class="n">row</span><span class="p">[</span><span class="s1">'R'</span><span class="p">]),</span> <span class="nb">str</span><span class="p">(</span><span class="n">row</span><span class="p">[</span><span class="s1">'F'</span><span class="p">]),</span> <span class="nb">str</span><span class="p">(</span><span class="n">row</span><span class="p">[</span><span class="s1">'M'</span><span class="p">])</span>  <span class="c1"># Преобразуйте в строки</span>
            <span class="n">rfm_score</span> <span class="o">=</span> <span class="nb">str</span><span class="p">(</span><span class="n">row</span><span class="p">[</span><span class="s1">'RFM_Score'</span><span class="p">])</span>  <span class="c1"># Преобразуйте в строку</span>
        <span class="k">except</span> <span class="ne">KeyError</span> <span class="k">as</span> <span class="n">e</span><span class="p">:</span>
            <span class="nb">print</span><span class="p">(</span><span class="sa">f</span><span class="s2">"Ошибка KeyError: Отсутствует столбец </span><span class="si">{</span><span class="n">e</span><span class="si">}</span><span class="s2"> в строке."</span><span class="p">)</span>
            <span class="k">return</span> <span class="s1">'Unknown'</span>  <span class="c1"># Или какое-то другое значение по умолчанию</span>
        <span class="k">except</span> <span class="ne">TypeError</span> <span class="k">as</span> <span class="n">e</span><span class="p">:</span>
            <span class="nb">print</span><span class="p">(</span><span class="sa">f</span><span class="s2">"Ошибка TypeError: Неверный тип данных в строке: </span><span class="si">{</span><span class="n">e</span><span class="si">}</span><span class="s2">"</span><span class="p">)</span>
            <span class="k">return</span> <span class="s1">'Unknown'</span>  <span class="c1"># Или какое-то другое значение по умолчанию</span>

        <span class="k">if</span> <span class="n">rfm_score</span> <span class="o">==</span> <span class="s1">'444'</span><span class="p">:</span>
            <span class="k">return</span> <span class="s1">'Best Customers'</span>
        <span class="k">elif</span> <span class="n">r</span> <span class="ow">in</span> <span class="p">[</span><span class="s1">'4'</span><span class="p">,</span> <span class="s1">'3'</span><span class="p">]</span> <span class="ow">and</span> <span class="n">f</span> <span class="ow">in</span> <span class="p">[</span><span class="s1">'3'</span><span class="p">,</span> <span class="s1">'4'</span><span class="p">]:</span>
            <span class="k">return</span> <span class="s1">'Loyal Customers'</span>
        <span class="k">elif</span> <span class="n">r</span> <span class="ow">in</span> <span class="p">[</span><span class="s1">'4'</span><span class="p">,</span> <span class="s1">'3'</span><span class="p">]</span> <span class="ow">and</span> <span class="n">m</span> <span class="ow">in</span> <span class="p">[</span><span class="s1">'3'</span><span class="p">,</span> <span class="s1">'4'</span><span class="p">]:</span>
            <span class="k">return</span> <span class="s1">'Big Spenders'</span>
        <span class="k">elif</span> <span class="n">r</span> <span class="o">==</span> <span class="s1">'4'</span> <span class="ow">and</span> <span class="n">f</span> <span class="o">==</span> <span class="s1">'1'</span> <span class="ow">and</span> <span class="n">m</span> <span class="ow">in</span> <span class="p">[</span><span class="s1">'3'</span><span class="p">,</span> <span class="s1">'4'</span><span class="p">]:</span>
            <span class="k">return</span> <span class="s1">'New Big Spenders'</span>
        <span class="k">elif</span> <span class="n">r</span> <span class="o">==</span> <span class="s1">'4'</span> <span class="ow">and</span> <span class="n">f</span> <span class="o">==</span> <span class="s1">'1'</span> <span class="ow">and</span> <span class="n">m</span> <span class="ow">in</span> <span class="p">[</span><span class="s1">'1'</span><span class="p">,</span> <span class="s1">'2'</span><span class="p">]:</span>
            <span class="k">return</span> <span class="s1">'New Low Spenders'</span>
        <span class="k">elif</span> <span class="n">r</span> <span class="o">==</span> <span class="s1">'4'</span> <span class="ow">and</span> <span class="n">f</span> <span class="o">==</span> <span class="s1">'1'</span><span class="p">:</span>
            <span class="k">return</span> <span class="s1">'New Customers'</span>
        <span class="k">elif</span> <span class="n">r</span> <span class="o">==</span> <span class="s1">'1'</span> <span class="ow">and</span> <span class="n">f</span> <span class="o">==</span> <span class="s1">'1'</span><span class="p">:</span>
            <span class="k">return</span> <span class="s1">'Lost Customers'</span>
        <span class="k">elif</span> <span class="n">r</span> <span class="ow">in</span> <span class="p">[</span><span class="s1">'1'</span><span class="p">,</span> <span class="s1">'2'</span><span class="p">]</span> <span class="ow">and</span> <span class="n">f</span> <span class="ow">in</span> <span class="p">[</span><span class="s1">'3'</span><span class="p">,</span> <span class="s1">'4'</span><span class="p">]:</span>
            <span class="k">return</span> <span class="s1">'Churning Loyalists'</span>
        <span class="k">elif</span> <span class="n">r</span> <span class="ow">in</span> <span class="p">[</span><span class="s1">'1'</span><span class="p">,</span> <span class="s1">'2'</span><span class="p">]</span> <span class="ow">and</span> <span class="n">m</span> <span class="ow">in</span> <span class="p">[</span><span class="s1">'3'</span><span class="p">,</span> <span class="s1">'4'</span><span class="p">]:</span>
            <span class="k">return</span> <span class="s1">'Churning Spenders'</span>
        <span class="k">elif</span> <span class="n">r</span> <span class="o">==</span> <span class="s1">'4'</span> <span class="ow">and</span> <span class="n">m</span> <span class="o">==</span> <span class="s1">'1'</span><span class="p">:</span>
            <span class="k">return</span> <span class="s1">'Discount Shoppers'</span>
        <span class="k">elif</span> <span class="n">r</span> <span class="ow">in</span> <span class="p">[</span><span class="s1">'3'</span><span class="p">,</span> <span class="s1">'4'</span><span class="p">]</span> <span class="ow">and</span> <span class="n">f</span> <span class="ow">in</span> <span class="p">[</span><span class="s1">'1'</span><span class="p">,</span> <span class="s1">'2'</span><span class="p">]:</span>
            <span class="k">return</span> <span class="s1">'Promising'</span>
        <span class="k">elif</span> <span class="n">r</span> <span class="o">==</span> <span class="s1">'1'</span> <span class="ow">and</span> <span class="n">m</span> <span class="o">==</span> <span class="s1">'4'</span><span class="p">:</span>
            <span class="k">return</span> <span class="s1">'Resurrect Spenders'</span>
        <span class="k">elif</span> <span class="n">f</span> <span class="o">==</span> <span class="s1">'4'</span> <span class="ow">and</span> <span class="n">m</span> <span class="o">==</span> <span class="s1">'1'</span><span class="p">:</span>
            <span class="k">return</span> <span class="s1">'Frequent Low Spenders'</span>
        <span class="k">elif</span> <span class="n">rfm_score</span> <span class="ow">in</span> <span class="p">[</span><span class="s1">'222'</span><span class="p">,</span> <span class="s1">'223'</span><span class="p">,</span> <span class="s1">'232'</span><span class="p">,</span> <span class="s1">'322'</span><span class="p">]:</span>
            <span class="k">return</span> <span class="s1">'Mid-Range'</span>
        <span class="k">else</span><span class="p">:</span>
            <span class="k">return</span> <span class="s1">'Other Customers'</span>

    <span class="c1"># Обработайте пропущенные значения перед применением segment_customers</span>
    <span class="n">rfm_table</span><span class="p">[[</span><span class="s1">'R'</span><span class="p">,</span> <span class="s1">'F'</span><span class="p">,</span> <span class="s1">'M'</span><span class="p">,</span> <span class="s1">'RFM_Score'</span><span class="p">]]</span> <span class="o">=</span> <span class="n">rfm_table</span><span class="p">[[</span><span class="s1">'R'</span><span class="p">,</span> <span class="s1">'F'</span><span class="p">,</span> <span class="s1">'M'</span><span class="p">,</span> <span class="s1">'RFM_Score'</span><span class="p">]]</span><span class="o">.</span><span class="n">fillna</span><span class="p">(</span><span class="s1">'0'</span><span class="p">)</span>  <span class="c1"># Замените NaN на '0'</span>

    <span class="n">rfm_table</span><span class="p">[</span><span class="s1">'Segment'</span><span class="p">]</span> <span class="o">=</span> <span class="n">rfm_table</span><span class="o">.</span><span class="n">apply</span><span class="p">(</span><span class="n">segment_customers</span><span class="p">,</span> <span class="n">axis</span><span class="o">=</span><span class="mi">1</span><span class="p">)</span>

    <span class="c1"># Подготовка данных для графика</span>
    <span class="n">segment_counts</span> <span class="o">=</span> <span class="n">rfm_table</span><span class="p">[</span><span class="s1">'Segment'</span><span class="p">]</span><span class="o">.</span><span class="n">value_counts</span><span class="p">()</span>
    <span class="n">segments</span> <span class="o">=</span> <span class="n">segment_counts</span><span class="o">.</span><span class="n">index</span>  <span class="c1"># Получаем названия сегментов</span>

    <span class="c1"># ------------------  Улучшения внешнего вида  ------------------</span>
    <span class="c1"># 1. Выбираем цветовую палитру:</span>
    <span class="c1"># Вариант 1:  Используем встроенные палитры matplotlib</span>
    <span class="c1"># colors = plt.cm.get_cmap('tab20c', len(segments))  # Например, 'tab20c'</span>
    <span class="c1"># Вариант 2: Создаем пользовательскую палитру (более гибкий вариант):</span>
    <span class="c1"># colors = ['#ff9999', '#66b3ff', '#99ff99', '#ffcc99', '#c2c2f0', '#ffb3e6', '#e6b8af', '#a9d18e', '#e2e2e2']  # Пример</span>
    <span class="c1"># Вариант 3:  Использование seaborn</span>
    <span class="c1">#colors = sns.color_palette('pastel', len(segments)) # Pastel colors</span>
    <span class="n">colors</span> <span class="o">=</span> <span class="n">sns</span><span class="o">.</span><span class="n">color_palette</span><span class="p">(</span><span class="s1">'plasma'</span><span class="p">,</span> <span class="nb">len</span><span class="p">(</span><span class="n">segments</span><span class="p">))</span> <span class="c1"># Set2</span>

    <span class="c1"># 2. Создание круговой диаграммы</span>
    <span class="n">plt</span><span class="o">.</span><span class="n">figure</span><span class="p">(</span><span class="n">figsize</span><span class="o">=</span><span class="p">(</span><span class="mi">12</span><span class="p">,</span> <span class="mi">9</span><span class="p">))</span>  <span class="c1"># Увеличим размер графика</span>
    <span class="n">wedges</span><span class="p">,</span> <span class="n">texts</span><span class="p">,</span> <span class="n">autotexts</span> <span class="o">=</span> <span class="n">plt</span><span class="o">.</span><span class="n">pie</span><span class="p">(</span><span class="n">segment_counts</span><span class="p">,</span>
                                        <span class="n">autopct</span><span class="o">=</span><span class="s1">'</span><span class="si">%1.1f%%</span><span class="s1">'</span><span class="p">,</span>
                                        <span class="n">startangle</span><span class="o">=</span><span class="mi">140</span><span class="p">,</span>
                                        <span class="n">colors</span><span class="o">=</span><span class="n">colors</span><span class="p">,</span>  <span class="c1"># Используем цвета из палитры</span>
                                        <span class="n">textprops</span><span class="o">=</span><span class="nb">dict</span><span class="p">(</span><span class="n">color</span><span class="o">=</span><span class="s2">"black"</span><span class="p">,</span> <span class="n">weight</span><span class="o">=</span><span class="s1">'bold'</span><span class="p">,</span> <span class="n">fontsize</span><span class="o">=</span><span class="mi">10</span><span class="p">))</span> <span class="c1"># Настроим параметры текста на графике</span>

    <span class="c1"># 3. Улучшаем внешний вид подписей (если нужно):</span>
    <span class="c1">#  Настройка подписей к сегментам (если нужно):</span>
    <span class="c1"># for autotext in autotexts:</span>
    <span class="c1">#     autotext.set_color('white')  # Цвет подписей с процентами</span>

    <span class="c1"># 4. Создание легенды с более приятным отображением</span>
    <span class="n">plt</span><span class="o">.</span><span class="n">legend</span><span class="p">(</span><span class="n">wedges</span><span class="p">,</span> <span class="n">segments</span><span class="p">,</span>
              <span class="n">title</span><span class="o">=</span><span class="s2">"Segments"</span><span class="p">,</span>
              <span class="n">loc</span><span class="o">=</span><span class="s2">"center left"</span><span class="p">,</span>
              <span class="n">bbox_to_anchor</span><span class="o">=</span><span class="p">(</span><span class="mi">1</span><span class="p">,</span> <span class="mi">0</span><span class="p">,</span> <span class="mf">0.5</span><span class="p">,</span> <span class="mi">1</span><span class="p">),</span>
              <span class="n">fontsize</span><span class="o">=</span><span class="mi">10</span><span class="p">)</span>

    <span class="n">plt</span><span class="o">.</span><span class="n">title</span><span class="p">(</span><span class="sa">f</span><span class="s1">'</span><span class="si">{</span><span class="n">title</span><span class="si">}</span><span class="s1">'</span><span class="p">,</span> <span class="n">fontsize</span><span class="o">=</span><span class="mi">18</span><span class="p">,</span> <span class="n">fontweight</span><span class="o">=</span><span class="s1">'bold'</span><span class="p">)</span>  <span class="c1">#  Более жирный заголовок</span>

    <span class="c1"># Улучшение внешнего вида</span>
    <span class="n">plt</span><span class="o">.</span><span class="n">axis</span><span class="p">(</span><span class="s1">'equal'</span><span class="p">)</span>  <span class="c1"># Чтобы круговая диаграмма была кругом</span>
    <span class="n">plt</span><span class="o">.</span><span class="n">tight_layout</span><span class="p">()</span>  <span class="c1"># Автоматическая настройка параметров подложки для графика</span>

    <span class="c1"># Отображение графика</span>
    <span class="n">plt</span><span class="o">.</span><span class="n">show</span><span class="p">()</span>

    <span class="c1"># Вывод количества клиентов в каждом сегменте (полезно для анализа)</span>
    <span class="nb">print</span><span class="p">(</span><span class="n">rfm_table</span><span class="p">[</span><span class="s1">'Segment'</span><span class="p">]</span><span class="o">.</span><span class="n">value_counts</span><span class="p">())</span>
    
<span class="n">create_segment_distribution_pie</span><span class="p">(</span><span class="n">RFM_price</span><span class="p">,</span> <span class="n">title</span><span class="o">=</span><span class="s2">"Customer Segment Distribution"</span><span class="p">)</span>
</pre>
