  <div class="jp-Cell jp-CodeCell jp-Notebook-cell">
    <div class="jp-Cell-inputWrapper" tabindex="0">
      <div class="jp-Collapser jp-InputCollapser jp-Cell-inputCollapser"></div>
      <div>
        <div class="jp-CodeMirrorEditor jp-Editor jp-InputArea-editor" data-type="inline">
          <div class="cm-editor cm-s-jupyter">
            <div class="highlight hl-ipython3">
              <pre><span class="kn">import</span> <span class="nn">seaborn</span> <span class="k">as</span> <span class="nn">sns</span>
<span class="kn">import</span> <span class="nn">matplotlib.pyplot</span> <span class="k">as</span> <span class="nn">plt</span>

<span class="k">def</span> <span class="nf">plot_rfm_score_distribution</span><span class="p">(</span><span class="n">rfm_table</span><span class="p">,</span> <span class="n">title</span><span class="o">=</span><span class="s1">'Distribution of RFM Score'</span><span class="p">,</span> <span class="n">palette</span><span class="o">=</span><span class="s1">'viridis'</span><span class="p">):</span>
<span class="w">    </span><span class="sd">"""</span>
<span class="sd">    Создает countplot распределения RFM-скора с отображением процентов на столбцах.</span>

<span class="sd">    Args:</span>
<span class="sd">        rfm_table (pd.DataFrame): DataFrame с RFM-данными (должен содержать столбцы 'R', 'F', 'M').</span>
<span class="sd">        title (str): Заголовок графика.</span>
<span class="sd">        palette (str): Цветовая палитра для графика (например, 'viridis', 'plasma', 'magma').</span>
<span class="sd">    """</span>

    <span class="c1"># Вычисляем RFM Score, если его еще нет</span>
    <span class="k">if</span> <span class="s1">'RFM_Score'</span> <span class="ow">not</span> <span class="ow">in</span> <span class="n">rfm_table</span><span class="o">.</span><span class="n">columns</span><span class="p">:</span>
        <span class="n">rfm_table</span><span class="p">[</span><span class="s1">'RFM_Score'</span><span class="p">]</span> <span class="o">=</span> <span class="n">rfm_table</span><span class="p">[</span><span class="s1">'R'</span><span class="p">]</span> <span class="o">+</span> <span class="n">rfm_table</span><span class="p">[</span><span class="s1">'F'</span><span class="p">]</span> <span class="o">+</span> <span class="n">rfm_table</span><span class="p">[</span><span class="s1">'M'</span><span class="p">]</span>

    <span class="n">plt</span><span class="o">.</span><span class="n">figure</span><span class="p">(</span><span class="n">figsize</span><span class="o">=</span><span class="p">(</span><span class="mi">12</span><span class="p">,</span> <span class="mi">7</span><span class="p">))</span>
    <span class="n">ax</span> <span class="o">=</span> <span class="n">sns</span><span class="o">.</span><span class="n">countplot</span><span class="p">(</span><span class="n">x</span><span class="o">=</span><span class="n">rfm_table</span><span class="p">[</span><span class="s1">'RFM_Score'</span><span class="p">],</span> <span class="n">palette</span><span class="o">=</span><span class="n">palette</span><span class="p">)</span>
    <span class="n">plt</span><span class="o">.</span><span class="n">title</span><span class="p">(</span><span class="n">title</span><span class="p">,</span> <span class="n">fontsize</span><span class="o">=</span><span class="mi">16</span><span class="p">)</span>
    <span class="n">plt</span><span class="o">.</span><span class="n">xlabel</span><span class="p">(</span><span class="s1">'RFM Score (R+F+M)'</span><span class="p">,</span> <span class="n">fontsize</span><span class="o">=</span><span class="mi">12</span><span class="p">)</span>
    <span class="n">plt</span><span class="o">.</span><span class="n">ylabel</span><span class="p">(</span><span class="s1">'Number of Customers'</span><span class="p">,</span> <span class="n">fontsize</span><span class="o">=</span><span class="mi">12</span><span class="p">)</span>
    <span class="n">plt</span><span class="o">.</span><span class="n">xticks</span><span class="p">(</span><span class="n">rotation</span><span class="o">=</span><span class="mi">45</span><span class="p">,</span> <span class="n">ha</span><span class="o">=</span><span class="s1">'right'</span><span class="p">)</span>
    <span class="n">sns</span><span class="o">.</span><span class="n">despine</span><span class="p">()</span>

    <span class="c1"># Добавляем подписи процентов на столбцы</span>
    <span class="n">total</span> <span class="o">=</span> <span class="nb">len</span><span class="p">(</span><span class="n">rfm_table</span><span class="p">)</span>
    <span class="k">for</span> <span class="n">p</span> <span class="ow">in</span> <span class="n">ax</span><span class="o">.</span><span class="n">patches</span><span class="p">:</span>
        <span class="n">percentage</span> <span class="o">=</span> <span class="s1">'</span><span class="si">{:.1f}</span><span class="s1">%'</span><span class="o">.</span><span class="n">format</span><span class="p">(</span><span class="mi">100</span> <span class="o">*</span> <span class="n">p</span><span class="o">.</span><span class="n">get_height</span><span class="p">()</span><span class="o">/</span><span class="n">total</span><span class="p">)</span>
        <span class="n">x</span> <span class="o">=</span> <span class="n">p</span><span class="o">.</span><span class="n">get_x</span><span class="p">()</span> <span class="o">+</span> <span class="n">p</span><span class="o">.</span><span class="n">get_width</span><span class="p">()</span> <span class="o">/</span> <span class="mi">2</span>
        <span class="n">y</span> <span class="o">=</span> <span class="n">p</span><span class="o">.</span><span class="n">get_height</span><span class="p">()</span> <span class="o">+</span> <span class="mf">0.5</span>  <span class="c1"># Немного сместим подпись вверх</span>
        <span class="n">ax</span><span class="o">.</span><span class="n">annotate</span><span class="p">(</span><span class="n">percentage</span><span class="p">,</span> <span class="p">(</span><span class="n">x</span><span class="p">,</span> <span class="n">y</span><span class="p">),</span> <span class="n">ha</span><span class="o">=</span><span class="s1">'center'</span><span class="p">,</span> <span class="n">fontsize</span><span class="o">=</span><span class="mi">10</span><span class="p">)</span>

    <span class="n">plt</span><span class="o">.</span><span class="n">tight_layout</span><span class="p">()</span>
    <span class="n">plt</span><span class="o">.</span><span class="n">show</span><span class="p">()</span>
    
<span class="n">plot_rfm_score_distribution</span><span class="p">(</span><span class="n">RFM_price</span><span class="p">,</span> <span class="n">title</span><span class="o">=</span><span class="s1">'Distribution of RFM Score'</span><span class="p">,</span> <span class="n">palette</span><span class="o">=</span><span class="s1">'plasma'</span><span class="p">)</span>

<span class="c1">#Над каждым столбцом указан процент клиентов, имеющих данный RFM-скор, от общего числа клиентов.</span>
</pre>
            </div>
          </div>
        </div>
      </div>
    </div>
