  <div class="jp-Cell jp-CodeCell jp-Notebook-cell">
    <div class="jp-Cell-inputWrapper" tabindex="0">
      <div class="jp-Collapser jp-InputCollapser jp-Cell-inputCollapser"></div>
      <div>
        <div class="jp-CodeMirrorEditor jp-Editor jp-InputArea-editor" data-type="inline">
          <div class="cm-editor cm-s-jupyter">
            <div class="highlight hl-ipython3">
              <pre><span class="kn">import</span> <span class="nn">pandas</span> <span class="k">as</span> <span class="nn">pd</span>
<span class="kn">import</span> <span class="nn">seaborn</span> <span class="k">as</span> <span class="nn">sns</span>
<span class="kn">import</span> <span class="nn">matplotlib.pyplot</span> <span class="k">as</span> <span class="nn">plt</span>


<span class="k">def</span> <span class="nf">plot_stacked_rfm_segment_distribution</span><span class="p">(</span><span class="n">rfm_table</span><span class="p">,</span> <span class="n">segment_col</span><span class="o">=</span><span class="s1">'Segment'</span><span class="p">,</span> <span class="n">rfm_score_col</span><span class="o">=</span><span class="s1">'RFM_Score'</span><span class="p">,</span>
                                               <span class="n">title</span><span class="o">=</span><span class="s1">'Stacked RFM Score Distribution by Segment'</span><span class="p">,</span> <span class="n">palette</span><span class="o">=</span><span class="s1">'plasma'</span><span class="p">):</span>
<span class="w">    </span><span class="sd">"""</span>
<span class="sd">    Создает stacked bar chart показывающую распределение RFM_Score по каждому Segment</span>
<span class="sd">    и добавляет количество клиентов на каждый сегмент.</span>

<span class="sd">    Args:</span>
<span class="sd">        rfm_table (pd.DataFrame): DataFrame с RFM-данными.</span>
<span class="sd">        segment_col (str): Название столбца с сегментами.</span>
<span class="sd">        rfm_score_col (str): Название столбца с RFM Score</span>
<span class="sd">        title (str): Заголовок графика.</span>
<span class="sd">        palette (str): Цветовая палитра.</span>
<span class="sd">    """</span>

    <span class="c1"># Группируем данные по Segment и RFM_Score, считаем количество</span>
    <span class="n">grouped_data</span> <span class="o">=</span> <span class="n">rfm_table</span><span class="o">.</span><span class="n">groupby</span><span class="p">([</span><span class="n">segment_col</span><span class="p">,</span> <span class="n">rfm_score_col</span><span class="p">])</span><span class="o">.</span><span class="n">size</span><span class="p">()</span><span class="o">.</span><span class="n">unstack</span><span class="p">(</span><span class="n">fill_value</span><span class="o">=</span><span class="mi">0</span><span class="p">)</span>

    <span class="c1"># Строим stacked bar chart</span>
    <span class="n">fig</span><span class="p">,</span> <span class="n">ax</span> <span class="o">=</span> <span class="n">plt</span><span class="o">.</span><span class="n">subplots</span><span class="p">(</span><span class="n">figsize</span><span class="o">=</span><span class="p">(</span><span class="mi">14</span><span class="p">,</span> <span class="mi">8</span><span class="p">))</span>  <span class="c1"># Получаем объект Axes для ручной настройки</span>
    <span class="n">grouped_data</span><span class="o">.</span><span class="n">plot</span><span class="p">(</span><span class="n">kind</span><span class="o">=</span><span class="s1">'bar'</span><span class="p">,</span> <span class="n">stacked</span><span class="o">=</span><span class="kc">True</span><span class="p">,</span> <span class="n">colormap</span><span class="o">=</span><span class="n">palette</span><span class="p">,</span> <span class="n">ax</span><span class="o">=</span><span class="n">ax</span><span class="p">)</span>  <span class="c1"># Передаем объект Axes</span>

    <span class="n">plt</span><span class="o">.</span><span class="n">title</span><span class="p">(</span><span class="n">title</span><span class="p">,</span> <span class="n">fontsize</span><span class="o">=</span><span class="mi">16</span><span class="p">)</span>
    <span class="n">plt</span><span class="o">.</span><span class="n">xlabel</span><span class="p">(</span><span class="s1">'Segment'</span><span class="p">,</span> <span class="n">fontsize</span><span class="o">=</span><span class="mi">12</span><span class="p">)</span>
    <span class="n">plt</span><span class="o">.</span><span class="n">ylabel</span><span class="p">(</span><span class="s1">'Number of Customers'</span><span class="p">,</span> <span class="n">fontsize</span><span class="o">=</span><span class="mi">12</span><span class="p">)</span>
    <span class="n">plt</span><span class="o">.</span><span class="n">xticks</span><span class="p">(</span><span class="n">rotation</span><span class="o">=</span><span class="mi">45</span><span class="p">,</span> <span class="n">ha</span><span class="o">=</span><span class="s1">'right'</span><span class="p">)</span>

    <span class="c1"># Добавляем количество клиентов на каждый сегмент</span>
    <span class="k">for</span> <span class="n">p</span> <span class="ow">in</span> <span class="n">ax</span><span class="o">.</span><span class="n">patches</span><span class="p">:</span>
        <span class="n">width</span> <span class="o">=</span> <span class="n">p</span><span class="o">.</span><span class="n">get_width</span><span class="p">()</span>
        <span class="n">height</span> <span class="o">=</span> <span class="n">p</span><span class="o">.</span><span class="n">get_height</span><span class="p">()</span>
        <span class="n">x</span><span class="p">,</span> <span class="n">y</span> <span class="o">=</span> <span class="n">p</span><span class="o">.</span><span class="n">get_xy</span><span class="p">()</span>
        <span class="n">ax</span><span class="o">.</span><span class="n">annotate</span><span class="p">(</span><span class="sa">f</span><span class="s1">'</span><span class="si">{</span><span class="nb">int</span><span class="p">(</span><span class="n">height</span><span class="p">)</span><span class="si">}</span><span class="s1">'</span><span class="p">,</span> <span class="p">(</span><span class="n">x</span> <span class="o">+</span> <span class="n">width</span><span class="o">/</span><span class="mi">2</span><span class="p">,</span> <span class="n">y</span> <span class="o">+</span> <span class="n">height</span><span class="o">/</span><span class="mi">2</span><span class="p">),</span> <span class="n">ha</span><span class="o">=</span><span class="s1">'center'</span><span class="p">,</span> <span class="n">va</span><span class="o">=</span><span class="s1">'center'</span><span class="p">,</span> <span class="n">color</span><span class="o">=</span><span class="s1">'black'</span><span class="p">)</span>

    <span class="c1"># Получаем высоту графика в дюймах</span>
    <span class="n">chart_box</span> <span class="o">=</span> <span class="n">ax</span><span class="o">.</span><span class="n">get_position</span><span class="p">()</span>

    <span class="c1"># Изменяем высоту графика, чтобы оставить место для легенды</span>
    <span class="n">ax</span><span class="o">.</span><span class="n">set_position</span><span class="p">([</span><span class="n">chart_box</span><span class="o">.</span><span class="n">x0</span><span class="p">,</span> <span class="n">chart_box</span><span class="o">.</span><span class="n">y0</span> <span class="o">+</span> <span class="n">chart_box</span><span class="o">.</span><span class="n">height</span><span class="o">*</span><span class="mf">0.2</span><span class="p">,</span> <span class="n">chart_box</span><span class="o">.</span><span class="n">width</span><span class="p">,</span> <span class="n">chart_box</span><span class="o">.</span><span class="n">height</span><span class="o">*</span><span class="mf">0.8</span><span class="p">])</span>

    <span class="c1"># Размещаем легенду под графиком, в центре</span>
    <span class="n">ax</span><span class="o">.</span><span class="n">legend</span><span class="p">(</span><span class="n">title</span><span class="o">=</span><span class="s1">'RFM Score'</span><span class="p">,</span> <span class="n">loc</span><span class="o">=</span><span class="s1">'upper center'</span><span class="p">,</span> <span class="n">bbox_to_anchor</span><span class="o">=</span><span class="p">(</span><span class="mf">0.5</span><span class="p">,</span> <span class="o">-</span><span class="mf">0.3</span><span class="p">),</span> <span class="n">ncol</span><span class="o">=</span><span class="mi">4</span><span class="p">)</span>

    <span class="n">plt</span><span class="o">.</span><span class="n">show</span><span class="p">()</span>


<span class="n">plot_stacked_rfm_segment_distribution</span><span class="p">(</span><span class="n">RFM_price</span><span class="p">,</span> <span class="n">segment_col</span><span class="o">=</span><span class="s1">'Segment'</span><span class="p">,</span> <span class="n">rfm_score_col</span><span class="o">=</span><span class="s1">'RFM_Score'</span><span class="p">)</span>
</pre>
            </div>
          </div>
        </div>
      </div>
